function question(){const l=levels[game.level],i=Math.min(game.q,4);let q={...l.questions[i]};if(game.boss)q={...l.questions[4]};return q}
function startLevel(i){game.level=i;game.q=0;game.boss=false;game.selected.clear();game.wrong=0;game.correct=0;game.streak=0;game.bestStreak=0;game.roundWrong=0;game.roundCorrect=0;game.adaptive=0;show('playScreen');if(!sceneReady)initScene();loadQuestion()}
function loadQuestion(){const l=levels[game.level],q=question();game.selected.clear();game.answer=null;$('sceneLevel').innerHTML=`المستوى ${game.level+1} <span>• ${l.short}</span>`;$('questionCount').textContent=game.boss?'مواجهة الزبون الكبير 👑':`السؤال ${game.q+1} من ٥`;$('bossRibbon').style.display=game.boss?'block':'none';$('customerFace').textContent=game.boss?'🦁':['🧑‍🍳','🐻','🐰','🦊','🐼'][game.level];$('customerName').textContent=game.boss?'الزبون الكبير':`${['سامي الطاهي','دبدوب','لولو','فلفول','باندا'][game.level]}`;$('feedback').className='feedback';$('feedback').textContent='اختر الشرائح التي تُكوّن الكسر المطلوب.';$('choiceRow').style.display=game.level===2?'flex':'none';$('tray').className='tray';$('tray').textContent=game.level===4?'🧺 صندوق الجمع — اختر الشرائح ثم تحقّق':'🧺 الصينية فارغة — اسحب إليها الشرائح!';$('selectionLabel').textContent=game.level===4?'القطع في صندوق الجمع':game.level===3?'الشرائح قبل الدمج':'الشرائح المختارة';
