const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const http = require('http');
const fs = require('fs');
const path = require('path');
(async()=>{
 const html=fs.readFileSync('/home/runner/work/PlayGround/PlayGround/index.html');
 const server=http.createServer((req,res)=>{res.writeHead(200,{'content-type':'text/html'});res.end(html)});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));
 const url=`http://127.0.0.1:${server.address().port}/`;
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const errors=[];
 const page=await browser.newPage({viewport:{width:1365,height:900},deviceScaleFactor:1});
 page.on('pageerror',e=>errors.push('pageerror: '+e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
 await page.goto(url,{waitUntil:'networkidle',timeout:60000});
 await page.waitForTimeout(1500);
 const initial=await page.evaluate(()=>({home:document.querySelector('#home').className,level:document.querySelector('#playScreen').className,three:!!window.THREE,canvas:!!document.querySelector('#scene').getContext('webgl'),order:document.querySelector('#orderText').textContent}));
 await page.screenshot({path:'/tmp/opencode/pizza-current-desktop-home.png',fullPage:true});
 await page.click('#startBtn');
 await page.click('.level-card');
 await page.waitForTimeout(1200);
 await page.screenshot({path:'/tmp/opencode/pizza-current-desktop-game.png',fullPage:true});
 const before=await page.locator('#selectionValue').textContent();
 const coords=await page.evaluate(()=>{
  const mesh=window.plates[0][0];
  const a=-Math.PI/2+Math.PI/2;
  const v=new THREE.Vector3(.65*Math.cos(a),0,-.65*Math.sin(a));
  mesh.localToWorld(v);v.project(camera);
  const r=document.querySelector('#scene').getBoundingClientRect();
  const x=r.left+(v.x+1)*r.width/2,y=r.top+(1-v.y)*r.height/2;
  const tr=document.querySelector('#tray').getBoundingClientRect();
  return {x,y,tray:{x:tr.left+tr.width/2,y:tr.top+tr.height/2},inside:{x:r.left<=x&&x<=r.right,y:r.top<=y&&y<=r.bottom},canvas:{w:r.width,h:r.height},world:{x:v.x,y:v.y,z:v.z}};
 });
 await page.mouse.move(coords.x,coords.y);await page.mouse.down();await page.mouse.move(coords.tray.x,coords.tray.y,{steps:10});await page.mouse.up();
 await page.waitForTimeout(250);
 const afterDrag=await page.locator('#selectionValue').textContent();
 const trayText=await page.locator('#tray').textContent();
 // verify click also toggles a different visible slice, using an exact projected point
 const clickPt=await page.evaluate(()=>{const mesh=window.plates[0][1];const a=-Math.PI/2+3*Math.PI/2;const v=new THREE.Vector3(.65*Math.cos(a),0,-.65*Math.sin(a));mesh.localToWorld(v);v.project(camera);const r=document.querySelector('#scene').getBoundingClientRect();return{x:r.left+(v.x+1)*r.width/2,y:r.top+(1-v.y)*r.height/2}});
 await page.mouse.click(clickPt.x,clickPt.y);await page.waitForTimeout(150);
 const afterClick=await page.locator('#selectionValue').textContent();
 await page.setViewportSize({width:390,height:844});await page.waitForTimeout(300);await page.screenshot({path:'/tmp/opencode/pizza-current-mobile-game.png',fullPage:true});
 const mobile=await page.evaluate(()=>({canvas:document.querySelector('#scene').getBoundingClientRect().toJSON(),tray:document.querySelector('#tray').getBoundingClientRect().toJSON(),selection:document.querySelector('#selectionValue').textContent(),pageWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth}));
 console.log(JSON.stringify({url,initial,before,coords,afterDrag,trayText,clickPt,afterClick,mobile,errors},null,2));
 await browser.close();server.close();
})().catch(e=>{console.error(e);process.exit(1)});

