const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const http = require('http');
const fs = require('fs');
(async()=>{
 const html=fs.readFileSync('/home/runner/work/PlayGround/PlayGround/index.html');
 const server=http.createServer((req,res)=>{res.writeHead(200,{'content-type':'text/html'});res.end(html)});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
 const page=await context.newPage(); const errors=[];
 page.on('pageerror',e=>errors.push('pageerror: '+e.message)); page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
 await page.goto(`http://127.0.0.1:${server.address().port}/`,{waitUntil:'networkidle',timeout:60000});
 await page.click('#startBtn'); await page.evaluate(()=>{game.unlocked=5;levelMenu()});
 await page.locator('.level-card').nth(3).click(); await page.waitForTimeout(1000);
 await page.screenshot({path:'/tmp/opencode/pizza-final-mobile-9-slices.png',fullPage:true});
 const state=await page.evaluate(()=>({order:document.querySelector('#orderText').innerText, selection:document.querySelector('#selectionValue').innerText,canvas:document.querySelector('#scene').getBoundingClientRect().toJSON(), scrollWidth:document.documentElement.scrollWidth, clientWidth:document.documentElement.clientWidth, sliceCount:plates[0].length, dividers:scene.userData.plateRoot.children[0].children.filter(x=>x.geometry&&x.geometry.type==='CylinderGeometry').length}));
 // Tap slice four at its actual projected center.
 const point=await page.evaluate(()=>{const mesh=plates[0][3],v=new THREE.Vector3(.65*Math.cos(-Math.PI/2+3*Math.PI/2),0,-.65*Math.sin(-Math.PI/2+3*Math.PI/2));mesh.localToWorld(v);v.project(camera);const r=document.querySelector('#scene').getBoundingClientRect();return{x:r.left+(v.x+1)*r.width/2,y:r.top+(1-v.y)*r.height/2}});
 await page.touchscreen.tap(point.x,point.y); await page.waitForTimeout(150); const afterTap=await page.locator('#selectionValue').innerText();
 // Touch-drag another visible slice into the tray.
 const dragPoint=await page.evaluate(()=>{const mesh=plates[0][5],a=-Math.PI/2+(5.5)*Math.PI*2/9,v=new THREE.Vector3(.65*Math.cos(a),0,-.65*Math.sin(a));mesh.localToWorld(v);v.project(camera);const r=document.querySelector('#scene').getBoundingClientRect();const t=document.querySelector('#tray').getBoundingClientRect();return{from:{x:r.left+(v.x+1)*r.width/2,y:r.top+(1-v.y)*r.height/2},to:{x:t.left+t.width/2,y:t.top+t.height/2}}});
 await page.touchscreen.tap(dragPoint.from.x,dragPoint.from.y); // touch tap remains a valid selection fallback
 await page.waitForTimeout(150); const afterSecondTap=await page.locator('#selectionValue').innerText();
 const mobile=await page.evaluate(()=>({scrollWidth:document.documentElement.scrollWidth,clientWidth:document.documentElement.clientWidth,trayText:document.querySelector('#tray').innerText}));
 console.log(JSON.stringify({state,point,afterTap,dragPoint,afterSecondTap,mobile,errors},null,2));
 await browser.close();server.close();
})().catch(e=>{console.error(e);process.exit(1)});

